const readline = require("readline");

const rl = readline.createInterface({
  input: process.stdin,
  output: process.stdout,
});

rl.on("line", (line) => {
  console.log(getResult(line));
});

function getResult(s) {
  const stack = [];

  for (let c of s) {
    if (c < "A" || c > "z" || (c > "Z" && c < "a")) return 0;

    if (stack.length > 0 && stack.at(-1) == c) stack.pop();
    else stack.push(c);
  }

  return stack.length;
}

